LEVELS = ['very_simple','basic','standard','intermediate','advanced','specialized','expert']
PAY = [0.80,1.00,2.00,2.50,3.00,5.00,12.50]
MINUTES = [5,6,10,13,16,25,55]
# Level changes depend on a demonstrable review requirement, not just a label.
REVIEWS = [
('Use the supplied one-item example as the format reference.', 'Include a check against the supplied example.', 'Output follows the supplied example'),
('Check every completed item once against its source.', 'Add a short completion note listing any unresolved item IDs.', 'Unresolved items are explicitly listed or reported as none'),
('Check the completed batch for consistent terminology and formatting.', 'Include a batch-level consistency note.', 'The consistency note covers the complete batch'),
('Cross-check each result against the supplied acceptance notes and explain exceptions.', 'Include an exception table, even if it states none.', 'The exception table identifies affected item IDs or states none'),
('Independently repeat the highest-risk check for every item and compare both passes.', 'Include a two-pass comparison log with any discrepancies.', 'The two-pass log covers every item'),
('Apply both the supplied edge-case rules and the primary rules to every item; resolve conflicts explicitly.', 'Include a rule-conflict log with evidence for each resolution.', 'Each rule conflict has a source-backed resolution or an unresolved flag'),
('Review every item against the supplied expert rubric, then perform a second independent pass in reverse item order.', 'Include a rubric matrix, second-pass findings and a reasoned resolution for each disagreement.', 'The rubric matrix and reverse-order pass cover every item')]

def generate():
    records=[]
    for category,(prefix,count,submission,skills,subjects,raw) in DATA.items():
        families=[row.strip().split('|') for row in raw.strip().splitlines()]
        assert len(families)==8, category
        assert all(len(row)==6 for row in families), category
        for i in range(count):
            family=i%8
            variant=i//8
            level=(i+family)%7
            # Small batches, longer expert review, and bounded source items keep rates reasonable.
            n=[3,4,5,5,6,7,8][level]
            s=subjects[variant%len(subjects)]
            values={'n':n,'s':s}
            title,purpose,work1,work2,artifact,checks=[x.format(**values) for x in families[family]]
            extra,review_delivery,review_check=REVIEWS[level]
            scope='Work only from the supplied files, source packet and approved public sources explicitly named below; use the item IDs assigned to this batch.'
            if category in ('software_qa','web_usability','app_usability','accessibility'):
                scope='Use only the supplied test build, provided staging website, authorised beta app or supplied exports named below; use seeded demo data only.'
            if category=='business_verification':
                scope='Use only the approved public sources named below and public business contact details; do not contact businesses or collect private personal information.'
            if category=='app_usability':
                privacy=' Feedback is private to the commissioning client and must never be posted publicly.'
            else:
                privacy=''
            description=purpose+' '+('For this '+str(n)+'-item batch, good output follows the supplied '+LEVELS[level].replace('_',' ')+' review notes and keeps each result traceable to its source ID.')+privacy
            # Family-specific second sentence explains intended output; level is made concrete in step 4.
            description=purpose+' '+artifact+' '+('The '+str(n)+'-item batch must keep each result traceable to its supplied source ID.' if not privacy else privacy.strip())
            summary=title.rstrip('.')+'.'
            steps=[scope,work1,work2,extra,'Package the work with unchanged source IDs. '+review_delivery]
            record={
                'code':f'{prefix}-{i+1:03d}', 'category_slug':category,'title':title,'summary':summary,
                'description':description,'instructions':'\n'.join(f'{k}. {step}' for k,step in enumerate(steps,1)),
                'deliverables':artifact+' '+review_delivery,
                'verification_checklist':checks.split(';')+[review_check,'All '+str(n)+' assigned items have a source ID and a result or a documented blocker'],
                'submission_types':[submission], 'required_skills':skills,
                'difficulty':LEVELS[level], 'suggested_pay_usd':PAY[level],
                'estimated_minutes':MINUTES[level]
            }
            records.append(record)
    return records

EXPECTED={'data_entry':50,'online_research':45,'writing':45,'transcription':40,'translation':40,'graphic_design':45,'software_qa':45,'web_usability':40,'app_usability':40,'surveys':35,'business_verification':35,'ecommerce':35,'social_media':35,'seo_research':30,'spreadsheets':30,'education':30,'accessibility':25,'support_simulation':25,'audio_video':25,'tech_docs':25}
FIELDS={'code','category_slug','title','summary','description','instructions','deliverables','verification_checklist','submission_types','required_skills','difficulty','suggested_pay_usd','estimated_minutes'}
BANNED=['five-star','5-star','rating','install count','password','OTP']

def validate(records):
    assert len(records)==720, len(records)
    assert dict(collections.Counter(r['category_slug'] for r in records))==EXPECTED
    for field in ['code','title','description','instructions']:
        vals=[r[field] for r in records]
        assert len(vals)==len(set(vals)), 'duplicate '+field
    for r in records:
        assert set(r)==FIELDS
        assert re.fullmatch(r'[A-Z]{2,3}-\d{3}',r['code'])
        assert 0<len(r['title'])<=90,(r['code'],len(r['title']))
        assert 0<len(r['summary'])<=160 and not r['summary'].startswith('Handshake task:')
        assert len(re.split(r'(?<=[.!?])\s+',r['description'])) in (2,3),r['code']
        assert 4<=len(r['instructions'].splitlines())<=7
        assert all(line.startswith(str(i)+'. ') for i,line in enumerate(r['instructions'].splitlines(),1))
        assert 3<=len(r['verification_checklist'])<=5
        assert r['submission_types'] and set(r['submission_types'])<=set(['text','file','url','image','spreadsheet','document','audio','video'])
        assert 1<=len(r['required_skills'])<=4 and all(s==s.lower() for s in r['required_skills'])
        assert r['difficulty'] in LEVELS
        assert isinstance(r['estimated_minutes'],int) and 5<=r['estimated_minutes']<=240
        assert 8<=r['suggested_pay_usd']*60/r['estimated_minutes']<=16
        text=json.dumps(r,ensure_ascii=False).casefold()
        assert not any(term.casefold() in text for term in BANNED),r['code']
        if r['category_slug']=='app_usability':
            assert 'private to the commissioning client' in r['description'] and 'never be posted publicly' in r['description']
    for cat in EXPECTED:
        assert {r['difficulty'] for r in records if r['category_slug']==cat}==set(LEVELS),cat
    return {'total':len(records),'category_counts':EXPECTED,'unique_codes':720,'unique_titles':720,'unique_descriptions':720,'unique_instructions':720,'task_types_per_category':8,'difficulty_levels_per_category':7,'banned_term_matches':0,'hourly_rate_usd_range':[round(min(r['suggested_pay_usd']*60/r['estimated_minutes'] for r in records),2),round(max(r['suggested_pay_usd']*60/r['estimated_minutes'] for r in records),2)]}

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--output',type=Path,default=Path(__file__).resolve().with_name('task_templates.json'))
    args=parser.parse_args()
    records=generate()
    report=validate(records)
    args.output.parent.mkdir(parents=True,exist_ok=True)
    args.output.write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    assert json.loads(args.output.read_text(encoding='utf-8'))==records
    print(json.dumps(report,indent=2))

if __name__=='__main__':
    main()
